// Guide me for the page "{page}" on {portal} - made by the Guide Me Builder.
// Needs guide-kit.js, guide-kit.css and icons.js in the same folder as this file. Nothing is fetched: the tour is below.
import { openTour } from './guide-kit.js';

export const PAGE = {page_json};
export const SCRIPT = {script_json};
/** The card's words and the guide's settings travel with the tour: the kit itself carries none. */
export const WORDS = {words_json};
export const SETTINGS = {settings_json};

const KIT_CSS = new URL('./guide-kit.css', import.meta.url).href;

function addStyles() {
  const have = Array.from(document.querySelectorAll('link[rel="stylesheet"]')).some((l) => l.href === KIT_CSS);
  if (have) return;
  const link = document.createElement('link');
  link.rel = 'stylesheet';
  link.href = KIT_CSS;
  document.head.appendChild(link);
}

/** Open the tour now (a page may call this from a button of its own). */
export function openGuideMe() {
  addStyles();
  openTour(Object.assign({}, SCRIPT, { settings: Object.assign({}, SETTINGS, SCRIPT.voice || {}) }), { words: WORDS, screen: PAGE });
}

/** Wire every element marked data-guide-me - or, when the page has none, add a Guide me button to `where`. */
export function mountGuideMe(where = document.body) {
  addStyles();
  const found = Array.from(document.querySelectorAll('[data-guide-me]'));
  if (!found.length) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'gd-btn gd-float';
    b.setAttribute('data-guide-me', '');
    b.style.cssText = {button_style_json};
    b.textContent = {button_label_json};
    where.appendChild(b);
    found.push(b);
  }
  found.forEach((el) => el.addEventListener('click', openGuideMe));
  return found;
}

